CREATE TRIGGER `trg_approval_decision_bi` BEFORE INSERT ON `approval_decision` FOR EACH ROW
BEGIN
  DECLARE v_req BIGINT UNSIGNED;
  DECLARE v_kind VARCHAR(10);
  SET NEW.recorded_by = app_user();
  SET NEW.recorded_by_role = app_role();
  SET NEW.recorded_at = NOW(3);
  IF NEW.occurred_at IS NULL THEN SET NEW.occurred_at = NOW(3); END IF;
  IF @request_uuid IS NOT NULL THEN
    SET @req_seq = IFNULL(@req_seq, 0) + 1;
    SET NEW.request_uuid = CONCAT(LEFT(@request_uuid, 23), '-', LEFT(MD5(CONCAT('approval_decision', @req_seq)), 12));
  END IF;
  IF NEW.occurred_at > NOW(3) + INTERVAL 5 MINUTE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event time cannot be in the future'; END IF;
  IF NEW.is_backfilled = 0 AND NEW.occurred_at < NOW(3) - INTERVAL setting_int('backfill_threshold_minutes') MINUTE THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Old entry: mark it as backfilled (paper fallback) to record it';
  END IF;
  SELECT recorded_by INTO v_req FROM approval_request WHERE approval_request_id = NEW.approval_request_id; SELECT principal_kind INTO v_kind FROM staff WHERE staff_id = NEW.recorded_by; IF v_kind <> 'human' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'System principals cannot approve'; END IF; IF v_req = NEW.recorded_by THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'You cannot approve your own request'; END IF; IF NOT approver_has_authority(NEW.approval_request_id, NEW.recorded_by, NEW.recorded_by_role, NEW.authority_delegation_id, NEW.recorded_at) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'You are not allowed to approve this request (owner or valid delegation needed)'; END IF;
END$$

