CREATE TRIGGER `trg_appointment_slot_claim_bi` BEFORE INSERT ON `appointment_slot_claim` FOR EACH ROW
BEGIN
  DECLARE v_d1 BIGINT UNSIGNED;
  DECLARE v_d2 BIGINT UNSIGNED;
  SET NEW.recorded_by = app_user();
  SET NEW.recorded_by_role = app_role();
  SET NEW.recorded_at = NOW(3);
  IF NEW.occurred_at IS NULL THEN SET NEW.occurred_at = NOW(3); END IF;
  IF @request_uuid IS NOT NULL THEN
    SET @req_seq = IFNULL(@req_seq, 0) + 1;
    SET NEW.request_uuid = CONCAT(LEFT(@request_uuid, 23), '-', LEFT(MD5(CONCAT('appointment_slot_claim', @req_seq)), 12));
  END IF;
  IF NEW.occurred_at > NOW(3) + INTERVAL 5 MINUTE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event time cannot be in the future'; END IF;
  IF NEW.is_backfilled = 0 AND NEW.occurred_at < NOW(3) - INTERVAL setting_int('backfill_threshold_minutes') MINUTE THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Old entry: mark it as backfilled (paper fallback) to record it';
  END IF;
  SELECT doctor_staff_id INTO v_d1 FROM appointment WHERE appointment_id = NEW.appointment_id; SELECT doctor_staff_id INTO v_d2 FROM appointment_slot WHERE appointment_slot_id = NEW.appointment_slot_id; IF v_d1 <> v_d2 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Slot belongs to a different doctor'; END IF; IF slot_has_live_claim(NEW.appointment_slot_id, NEW.appointment_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Slot already booked for this doctor'; END IF;
END$$

