CREATE TRIGGER `trg_stock_movement_bi` BEFORE INSERT ON `stock_movement` FOR EACH ROW
BEGIN
  DECLARE v_onhand DECIMAL(12,2);
  DECLARE v_exp DATE;
  DECLARE v_mrp DECIMAL(12,2);
  DECLARE v_med BIGINT UNSIGNED;
  DECLARE v_dmed BIGINT UNSIGNED;
  SET NEW.recorded_by = app_user();
  SET NEW.recorded_by_role = app_role();
  SET NEW.recorded_at = NOW(3);
  IF NEW.occurred_at IS NULL THEN SET NEW.occurred_at = NOW(3); END IF;
  IF @request_uuid IS NOT NULL THEN
    SET @req_seq = IFNULL(@req_seq, 0) + 1;
    SET NEW.request_uuid = CONCAT(LEFT(@request_uuid, 23), '-', LEFT(MD5(CONCAT('stock_movement', @req_seq)), 12));
  END IF;
  IF NEW.occurred_at > NOW(3) + INTERVAL 5 MINUTE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event time cannot be in the future'; END IF;
  IF NEW.is_backfilled = 0 AND NEW.occurred_at < NOW(3) - INTERVAL setting_int('backfill_threshold_minutes') MINUTE THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Old entry: mark it as backfilled (paper fallback) to record it';
  END IF;
  SELECT expiry_date, mrp, medicine_id INTO v_exp, v_mrp, v_med FROM stock_batch WHERE stock_batch_id = NEW.stock_batch_id FOR UPDATE; IF NEW.movement_type = 'dispensed' THEN   IF v_exp < CURRENT_DATE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Expired batch cannot be dispensed'; END IF;   SELECT medicine_id INTO v_dmed FROM dispensing WHERE dispensing_id = NEW.dispensing_id;   IF v_dmed <> v_med THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Batch belongs to a different medicine'; END IF;   IF NEW.unit_price_snapshot <> v_mrp THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Dispensed price must equal the batch MRP'; END IF; END IF; IF NEW.movement_type IN ('adjustment','expired_writeoff') AND NOT approval_is_valid(NEW.approval_request_id, 'stock_adjustment,stock_writeoff') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'An approved adjustment/write-off request is required'; END IF; SELECT COALESCE(SUM(quantity_delta),0) INTO v_onhand FROM stock_movement WHERE stock_batch_id = NEW.stock_batch_id; IF v_onhand + NEW.quantity_delta < 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Not enough stock in this batch'; END IF;
END$$

