  INSERT INTO audit_log (action, entity_type, entity_id, old_values, new_values, reason)
  VALUES ('insert', 'counter_customer', CAST(NEW.`counter_customer_id` AS CHAR), NULL, JSON_OBJECT('counter_customer_id', NEW.`counter_customer_id`, 'phone', NEW.`phone`, 'temporary_code', NEW.`temporary_code`, 'display_name', NEW.`display_name`, 'created_at', NEW.`created_at`, 'created_by', NEW.`created_by`, 'updated_at', NEW.`updated_at`, 'updated_by', NEW.`updated_by`), @audit_reason);
END$$

CREATE TRIGGER `trg_counter_customer_au` AFTER UPDATE ON `counter_customer` FOR EACH ROW
BEGIN
  
  INSERT INTO audit_log (action, entity_type, entity_id, old_values, new_values, reason)
  VALUES ('update', 'counter_customer', CAST(NEW.`counter_customer_id` AS CHAR), JSON_OBJECT('counter_customer_id', OLD.`counter_customer_id`, 'phone', OLD.`phone`, 'temporary_code', OLD.`temporary_code`, 'display_name', OLD.`display_name`, 'created_at', OLD.`created_at`, 'created_by', OLD.`created_by`, 'updated_at', OLD.`updated_at`, 'updated_by', OLD.`updated_by`), JSON_OBJECT('counter_customer_id', NEW.`counter_customer_id`, 'phone', NEW.`phone`, 'temporary_code', NEW.`temporary_code`, 'display_name', NEW.`display_name`, 'created_at', NEW.`created_at`, 'created_by', NEW.`created_by`, 'updated_at', NEW.`updated_at`, 'updated_by', NEW.`updated_by`), @audit_reason);
END$$

CREATE TRIGGER `trg_counter_customer_link_event_bi` BEFORE INSERT ON `counter_customer_link_event` FOR EACH ROW
BEGIN
  
  SET NEW.recorded_by = app_user();
  SET NEW.recorded_by_role = app_role();
  SET NEW.recorded_at = NOW(3);
  IF NEW.occurred_at IS NULL THEN SET NEW.occurred_at = NOW(3); END IF;
  IF @request_uuid IS NOT NULL THEN
    SET @req_seq = IFNULL(@req_seq, 0) + 1;
    SET NEW.request_uuid = CONCAT(LEFT(@request_uuid, 23), '-', LEFT(MD5(CONCAT('counter_customer_link_event', @req_seq)), 12));
  END IF;
  IF NEW.occurred_at > NOW(3) + INTERVAL 5 MINUTE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event time cannot be in the future'; END IF;
  IF NEW.is_backfilled = 0 AND NEW.occurred_at < NOW(3) - INTERVAL setting_int('backfill_threshold_minutes') MINUTE THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Old entry: mark it as backfilled (paper fallback) to record it';
  END IF;
  
END$$

CREATE TRIGGER `trg_counter_customer_link_event_bu` BEFORE UPDATE ON `counter_customer_link_event` FOR EACH ROW
BEGIN
  
