CREATE TRIGGER `trg_dispensing_bi` BEFORE INSERT ON `dispensing` FOR EACH ROW
BEGIN
  DECLARE v_sched VARCHAR(4);
  DECLARE v_active TINYINT;
  SET NEW.recorded_by = app_user();
  SET NEW.recorded_by_role = app_role();
  SET NEW.recorded_at = NOW(3);
  IF NEW.occurred_at IS NULL THEN SET NEW.occurred_at = NOW(3); END IF;
  IF @request_uuid IS NOT NULL THEN
    SET @req_seq = IFNULL(@req_seq, 0) + 1;
    SET NEW.request_uuid = CONCAT(LEFT(@request_uuid, 23), '-', LEFT(MD5(CONCAT('dispensing', @req_seq)), 12));
  END IF;
  IF NEW.occurred_at > NOW(3) + INTERVAL 5 MINUTE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event time cannot be in the future'; END IF;
  IF NEW.is_backfilled = 0 AND NEW.occurred_at < NOW(3) - INTERVAL setting_int('backfill_threshold_minutes') MINUTE THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Old entry: mark it as backfilled (paper fallback) to record it';
  END IF;
  SELECT schedule_class, active INTO v_sched, v_active FROM medicine WHERE medicine_id = NEW.medicine_id; IF v_active = 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This medicine is inactive in the catalog'; END IF; IF NEW.source_type = 'otc' AND v_sched <> 'none' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Schedule H/H1/X medicines cannot be sold over the counter'; END IF;
END$$

