CREATE TRIGGER `trg_bill_line_bi` BEFORE INSERT ON `bill_line` FOR EACH ROW
BEGIN
  DECLARE v_fin INT;
  SET NEW.recorded_by = app_user();
  SET NEW.recorded_by_role = app_role();
  SET NEW.recorded_at = NOW(3);
  IF NEW.occurred_at IS NULL THEN SET NEW.occurred_at = NOW(3); END IF;
  IF @request_uuid IS NOT NULL THEN
    SET @req_seq = IFNULL(@req_seq, 0) + 1;
    SET NEW.request_uuid = CONCAT(LEFT(@request_uuid, 23), '-', LEFT(MD5(CONCAT('bill_line', @req_seq)), 12));
  END IF;
  IF NEW.occurred_at > NOW(3) + INTERVAL 5 MINUTE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event time cannot be in the future'; END IF;
  IF NEW.is_backfilled = 0 AND NEW.occurred_at < NOW(3) - INTERVAL setting_int('backfill_threshold_minutes') MINUTE THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Old entry: mark it as backfilled (paper fallback) to record it';
  END IF;
  SELECT COUNT(*) INTO v_fin FROM bill_finalization WHERE bill_id = NEW.bill_id; IF v_fin > 0 AND NEW.line_type NOT IN ('post_finalization_credit','post_finalization_debit','return_credit') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Bill is finalized; only approved credit/debit corrections are allowed'; END IF; IF NEW.line_type IN ('discount','free_service') AND NOT approval_is_valid(NEW.approval_request_id, 'discount,free_service') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'An approved discount request is required'; END IF; IF NEW.line_type IN ('post_finalization_credit','post_finalization_debit') AND NOT approval_is_valid(NEW.approval_request_id, 'post_finalization_bill_correction') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'An approved correction request is required'; END IF;
END$$

